60	  const capped = Math.min(pct, 1);
61	  return (
62	    <div className="w-full bg-gray-100 rounded-full h-2.5 overflow-hidden">
63	      <div
64	        className="h-2.5 rounded-full"
65	        style={{
66	          width: `${capped * 100}%`,
67	          backgroundColor: colour,
68	          transition: 'width 0.8s cubic-bezier(0.4, 0, 0.2, 1)',
69	        }}
70	      />
71	    </div>
72	  );
73	}
74	
75	function StarRating({ rating }) {
76	  const full  = Math.floor(rating);
77	  const half  = rating % 1 >= 0.5 ? 1 : 0;
78	  const empty = 5 - full - half;
79	  return (
80	    <div className="flex items-center gap-0.5">
81	      {Array.from({ length: full }).map((_, i) => (
82	        <Star key={`f${i}`} className="w-5 h-5 fill-amber-400 text-amber-400" />
83	      ))}
84	      {half === 1 && (
85	        <span className="relative w-5 h-5">
86	          <Star className="w-5 h-5 text-gray-200 absolute" />
87	          <span className="absolute left-0 top-0 overflow-hidden w-1/2">
88	            <Star className="w-5 h-5 fill-amber-400 text-amber-400" />
89	          </span>
90	        </span>
91	      )}
92	      {Array.from({ length: empty }).map((_, i) => (
93	        <Star key={`e${i}`} className="w-5 h-5 text-gray-200" />
94	      ))}
95	    </div>
96	  );
97	}
98	
99	function TrendTooltip({ active, payload, label }) {
100	  if (!active || !payload || !payload.length) return null;
101	  const pct = payload[0]?.value;
102	  const status = pct >= 100 ? 'GREEN' : pct >= 85 ? 'AMBER' : 'RED';
103	  return (
104	    <div className="bg-white border border-gray-200 rounded-lg shadow-lg p-3 text-xs">
105	      <p className="font-semibold text-gray-700 mb-1">{label}</p>
106	      <p className="font-bold" style={{ color: ragColour(status) }}>
107	        {pct?.toFixed(1)}% compliance
108	      </p>
109	      <p className={`mt-0.5 inline-block px-1.5 py-0.5 rounded text-[10px] font-medium ${ragBg(status)}`}>
110	        {status}
111	      </p>
112	    </div>
113	  );
114	}
115	
