148	      return acc;
149	    }, {});
150	  }, [dbShifts]);
151	
152	  const activeTrendDates = useMemo(() => {
153	    if (!dbShifts) return dummyTrendDates;
154	    const dates = [...new Set(dbShifts.map(s => s.date))].sort();
155	    return dates.slice(-14);
156	  }, [dbShifts]);
157	
158	  // Today's compliance
159	  const todayShifts = activeShiftsByDate[TODAY] || [];
