161	
162	  // 14-day period compliance
163	  const periodData = useMemo(() => {
164	    const daily = activeTrendDates.map(date => ({ date, shifts: activeShiftsByDate[date] || [] }));
165	    return calculatePeriodCompliance(daily, dummyFacility.residentCount);
