197	
198	  return (
199	    <div className="p-4 md:p-6 max-w-7xl mx-auto">
200	
201	      {/* ── Header ── */}
202	      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6">
203	        <div>
204	          <div className="flex items-center gap-2 flex-wrap">
