216	        </div>
217	        <div className={`flex items-center gap-2 px-3 py-2 rounded-lg font-medium text-sm shrink-0 ${
218	          todayData.isCompliant ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
