378	            <h2 className="font-semibold text-gray-900 mb-4">Today's Staff Breakdown</h2>
379	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
380	              {[
381	                { label: 'RN Minutes',     value: staffBreakdown.rn,     colour: '#3b82f6', bg: 'bg-blue-50',   border: 'border-blue-100'   },
382	                { label: 'EN Minutes',     value: staffBreakdown.en,     colour: '#8b5cf6', bg: 'bg-purple-50', border: 'border-purple-100' },
383	                { label: 'PCW Minutes',    value: staffBreakdown.pcw,    colour: '#22c55e', bg: 'bg-green-50',  border: 'border-green-100'  },
384	                { label: 'Agency Minutes', value: staffBreakdown.agency, colour: '#f59e0b', bg: 'bg-amber-50',  border: 'border-amber-100'  },
