390	                </div>
391	              ))}
392	            </div>
393	          </div>
394	        </div>
395	
396	        {/* ── Right column (1/3) ── */}
397	        <div className="space-y-4 md:space-y-6">
398	
399	          {/* AN-ACC Subsidy */}
400	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
401	            <div className="flex items-center gap-2 mb-4">
402	              <div className="p-1.5 rounded-lg bg-blue-50">
403	                <Activity className="w-3.5 h-3.5 text-blue-600" />
