406	            </div>
407	            <div className="space-y-3">
408	              <div className="flex justify-between text-sm">
409	                <span className="text-gray-500">Rate per resident</span>
410	                <span className="font-medium text-gray-900">{formatAUD(anAccRate)}/day</span>
411	              </div>
412	              <div className="flex justify-between text-sm">
413	                <span className="text-gray-500">Total daily subsidy</span>
414	                <span className="font-bold text-gray-900">{formatAUD(totalDailySubsidy)}</span>
415	              </div>
416	              <hr className="border-gray-100" />
417	              <div className="flex justify-between text-sm">
418	                <span className="text-gray-500">Amount protected</span>
419	                <span className="font-semibold text-green-600">{formatAUD(amountProtected)}</span>
420	              </div>
421	              <div className="flex justify-between text-sm">
422	                <span className="text-gray-500">Amount at risk</span>
423	                <span className={`font-semibold ${amountAtRisk > 0 ? 'text-red-600' : 'text-gray-400'}`}>
424	                  {amountAtRisk > 0 ? formatAUD(amountAtRisk) : '$0.00'}
425	                </span>
426	              </div>
427	            </div>
428	          </div>
429	
430	          {/* Star Rating */}
431	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-4 md:p-5 card-hover">
432	            <div className="flex items-center gap-2 mb-4">
433	              <div className="p-1.5 rounded-lg bg-amber-50">
434	                <Star className="w-3.5 h-3.5 text-amber-500" />
435	              </div>
436	              <h2 className="font-semibold text-gray-900">Star Rating</h2>
