468	                { label: 'Avg daily minutes',  value: `${Math.round(periodData.averageDailyMinutes).toLocaleString()} min`, colour: 'text-gray-900' },
469	                { label: 'Avg RN minutes',     value: `${Math.round(periodData.averageRNMinutes).toLocaleString()} min`,    colour: 'text-blue-600' },
