1	'use client';
2	
3	import { useState, useMemo } from 'react';
4	import { FileText, Download, RefreshCw, CheckCircle, XCircle } from 'lucide-react';
5	import { pdf } from '@react-pdf/renderer';
6	import { facility, manager, shiftsByDate, trendDates } from '@/lib/dummyData';
7	import { calculateDayCompliance, calculatePeriodCompliance, formatAUD, formatPct } from '@/lib/compliance';
8	import AuditPDF from './AuditPDF';
9	
10	function toIso(ddmmyyyy) {
11	  const [d, m, y] = ddmmyyyy.split('/');
12	  return `${y}-${m}-${d}`;
13	}
14	
15	function toDisplay(iso) {
16	  if (!iso) return '';
17	  const [y, m, d] = iso.split('-');
18	  return `${d}/${m}/${y}`;
19	}
20	
21	export default function ReportsPage() {
22	  const [fromDate,  setFromDate]  = useState('01/01/2026');
23	  const [toDate,    setToDate]    = useState('02/04/2026');
24	  const [generated, setGenerated] = useState(false);
25	  const [generating, setGenerating] = useState(false);
26	  const [downloading, setDownloading] = useState(false);
27	
28	  // Filter trendDates to the selected range
29	  const filteredDates = useMemo(() => {
30	    if (!generated) return [];
31	    try {
32	      const from = toIso(fromDate);
33	      const to   = toIso(toDate);
34	      return trendDates.filter(d => d >= from && d <= to);
35	    } catch { return trendDates; }
36	  }, [generated, fromDate, toDate]);
37	
38	  const periodData = useMemo(() => {
39	    if (!generated || filteredDates.length === 0) return null;
40	    const daily = filteredDates.map(date => ({ date, shifts: shiftsByDate[date] || [] }));
41	    return calculatePeriodCompliance(daily, facility.residentCount);
42	  }, [generated, filteredDates]);
43	
44	  // Staff type breakdown
45	  const staffBreakdown = useMemo(() => {
46	    if (!periodData) return null;
47	    const allShifts = filteredDates.flatMap(d => shiftsByDate[d] || []);
48	    const byType = (type) => allShifts.filter(s => s.staffType === type).reduce((a, s) => a + s.durationMinutes, 0);
49	    const agency = allShifts.filter(s => s.employmentType === 'Agency').reduce((a, s) => a + s.durationMinutes, 0);
50	    const perm   = allShifts.filter(s => s.employmentType !== 'Agency').reduce((a, s) => a + s.durationMinutes, 0);
51	    const total  = allShifts.reduce((a, s) => a + s.durationMinutes, 0);
52	    return {
53	      rn:      byType('RN'),
54	      en:      byType('EN'),
55	      pcw:     byType('PCW'),
56	      agency,
57	      permanent: perm,
58	      agencyPct: total > 0 ? agency / total : 0,
59	      permPct:   total > 0 ? perm   / total : 0,
60	    };
61	  }, [periodData, filteredDates]);
62	
63	  const overallResult = periodData
64	    ? periodData.overallCompliancePct >= 1 ? 'Met' : 'Not Met'
65	    : null;
66	
67	  function handleGenerate(e) {
68	    e.preventDefault();
69	    setGenerating(true);
70	    setTimeout(() => {
71	      setGenerated(true);
72	      setGenerating(false);
73	    }, 800);
74	  }
75	
76	  async function handleDownload() {
77	    if (!periodData || !staffBreakdown) return;
78	    setDownloading(true);
79	    try {
80	      const blob = await pdf(
81	        <AuditPDF
82	          facility={facility}
83	          manager={manager}
84	          fromDate={fromDate}
85	          toDate={toDate}
86	          periodData={periodData}
87	          staffBreakdown={staffBreakdown}
88	          filteredDates={filteredDates}
89	          shiftsByDate={shiftsByDate}
90	        />
91	      ).toBlob();
92	      const url = URL.createObjectURL(blob);
93	      const a   = document.createElement('a');
94	      a.href = url;
95	      a.download = `CareMinutes_AuditReport_${fromDate.replace(/\//g,'-')}_${toDate.replace(/\//g,'-')}.pdf`;
96	      a.click();
97	      URL.revokeObjectURL(url);
98	    } catch (err) {
99	      console.error('PDF generation error:', err);
100	    }
101	    setDownloading(false);
102	  }
103	
104	  return (
105	    <div className="p-4 md:p-6 max-w-5xl mx-auto">
106	
107	      {/* ── Header ── */}
108	      <div className="mb-6">
109	        <h1 className="text-xl font-bold text-gray-900">Compliance Reports</h1>
110	        <p className="text-sm text-gray-500 mt-0.5">Generate ACQSC audit reports for any date range</p>
111	      </div>
112	
113	      {/* ── Report Generator ── */}
114	      <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 mb-6">
115	        <h2 className="font-semibold text-gray-900 mb-4 flex items-center gap-2">
116	          <FileText className="w-4 h-4 text-blue-600" /> ACQSC Audit Report
117	        </h2>
118	        <form onSubmit={handleGenerate} className="flex flex-col sm:flex-row gap-3 sm:items-end">
119	          <div className="flex-1 sm:flex-none">
120	            <label className="block text-xs font-medium text-gray-600 mb-1">From (DD/MM/YYYY)</label>
121	            <input
122	              type="text"
123	              value={fromDate}
124	              onChange={e => { setFromDate(e.target.value); setGenerated(false); }}
125	              placeholder="01/01/2026"
126	              className="w-full sm:w-36 border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
127	            />
128	          </div>
129	          <div className="flex-1 sm:flex-none">
130	            <label className="block text-xs font-medium text-gray-600 mb-1">To (DD/MM/YYYY)</label>
131	            <input
132	              type="text"
133	              value={toDate}
134	              onChange={e => { setToDate(e.target.value); setGenerated(false); }}
135	              placeholder="02/04/2026"
136	              className="w-full sm:w-36 border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
137	            />
138	          </div>
139	          <button
140	            type="submit"
141	            disabled={generating}
142	            className="flex items-center justify-center gap-2 px-5 py-2 bg-[#1e293b] text-white rounded-lg text-sm font-semibold hover:bg-slate-700 active:bg-slate-800 transition-colors disabled:opacity-60 w-full sm:w-auto"
143	          >
144	            {generating
145	              ? <><RefreshCw className="w-4 h-4 animate-spin" /> Generating…</>
146	              : <><FileText className="w-4 h-4" /> Generate Report</>
147	            }
148	          </button>
149	          {generated && (
150	            <button
151	              type="button"
152	              onClick={handleDownload}
153	              disabled={downloading}
154	              className="flex items-center justify-center gap-2 px-5 py-2 bg-[#22c55e] text-white rounded-lg text-sm font-semibold hover:bg-green-600 active:bg-green-700 transition-colors disabled:opacity-60 w-full sm:w-auto"
155	            >
156	              {downloading
157	                ? <><RefreshCw className="w-4 h-4 animate-spin" /> Preparing PDF…</>
158	                : <><Download className="w-4 h-4" /> Download PDF</>
159	              }
160	            </button>
161	          )}
162	        </form>
163	      </div>
164	
165	      {/* ── Report Preview ── */}
166	      {generated && periodData && staffBreakdown && (
167	        <div className="space-y-6">
168	
169	          {/* Cover info */}
170	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">
171	            <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4">
172	              <div>
173	                <div className="flex items-center gap-2 mb-1">
174	                  <span className="w-2 h-8 rounded bg-[#1e293b]" />
175	                  <div>
176	                    <h2 className="font-bold text-gray-900 text-lg">{facility.name}</h2>
177	                    <p className="text-xs text-gray-500">ABN: {facility.abn}</p>
178	                  </div>
179	                </div>
180	                <p className="text-sm text-gray-600 mt-2">
181	                  <span className="font-medium">Reporting period:</span> {fromDate} — {toDate}
182	                </p>
183	                <p className="text-sm text-gray-600">
184	                  <span className="font-medium">Generated:</span> {toDisplay('2026-04-02')} 09:14 AEST
185	                </p>
186	                <p className="text-sm text-gray-600">
187	                  <span className="font-medium">Prepared by:</span> {manager.name}
188	                </p>
189	              </div>
190	              <div className={`flex items-center gap-2 px-4 py-3 rounded-xl font-bold text-base self-start ${
191	                overallResult === 'Met' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
192	              }`}>
193	                {overallResult === 'Met'
194	                  ? <><CheckCircle className="w-5 h-5" /> Compliance Met</>
195	                  : <><XCircle className="w-5 h-5" /> Compliance Not Met</>
196	                }
197	              </div>
198	            </div>
199	          </div>
200	
201	          {/* Summary statistics */}
202	          <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5">
203	            <h3 className="font-semibold text-gray-900 mb-4">Executive Summary</h3>
204	            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
205	              {[
206	                { label: 'Total Days',           value: periodData.totalDays,                       unit: 'days'  },
207	                { label: 'Compliant Days',        value: periodData.compliantDays,                   unit: 'days', colour: 'text-green-600' },
208	                { label: 'Non-Compliant Days',    value: periodData.nonCompliantDays,                unit: 'days', colour: 'text-red-600'   },
209	                { label: 'Overall Compliance',    value: formatPct(periodData.overallCompliancePct), colour: periodData.overallCompliancePct >= 1 ? 'text-green-600' : 'text-red-600' },
210	                { label: 'Avg Daily Minutes',     value: `${Math.round(periodData.averageDailyMinutes).toLocaleString()} min` },
211	                { label: 'Total Penalties',       value: formatAUD(periodData.totalPenalty), colour: periodData.totalPenalty > 0 ? 'text-red-600' : 'text-green-600' },
212	              ].map(({ label, value, unit, colour }) => (
213	                <div key={label} className="bg-gray-50 rounded-lg p-3">
214	                  <p className="text-xs text-gray-500">{label}</p>
215	                  <p className={`text-lg font-bold mt-0.5 ${colour || 'text-gray-900'}`}>
216	                    {value}{unit ? <span className="text-xs font-normal text-gray-500 ml-1">{unit}</span> : ''}
217	                  </p>
218	                </div>
219	              ))}
220	            </div>
221	          </div>
